package tsgen

import (
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func renderedTypes(t *testing.T) string {
	t.Helper()
	return RenderTypes(parseSample(t), UnionsModule)
}

func TestRenderTypes(t *testing.T) {
	out := renderedTypes(t)

	for _, want := range []string{
		"// Code generated by internal/tsgen",
		"export interface Root {",
		"  timestamp: string;",
		"  host: Host;",
		"  items: Item[];",
		"  tags: string[];",
		"  count: number;",
		"  enabled: boolean;",
		"  state: State;",
		"/** Root is the top of the tree. */",
		"/** Name is the hostname. */",
		`export type State =`,
		`  | "up"`,
		`  | "down"`,
	} {
		if !strings.Contains(out, want) {
			t.Errorf("output is missing %q", want)
		}
	}

	// A pointer with omitempty is the one field the page has to branch on, so
	// it is the one spelled out in the interface.
	if !strings.Contains(out, "detail?: Detail | null;") {
		t.Error(`output is missing "detail?: Detail | null;"`)
	}

	// A slice is NOT spelled nullable, even though a nil one marshals to null:
	// the null is handled at the wire, in the schema, so several hundred call
	// sites do not each grow a guard for a state none of them can be handed.
	if strings.Contains(out, "items: Item[] | null") {
		t.Error("array fields must keep their optimistic spelling in the interface")
	}
}

// TestRenderTypes_NothingToImport covers the branch where no field is narrowed
// to a hand-written union: the file must not emit a dangling empty import,
// which does not compile.
func TestRenderTypes_NothingToImport(t *testing.T) {
	const src = `package types

type Root struct {
	Name string ` + "`json:\"name\"`" + `
}
`
	model, err := ParseSource("plain.go", src, []string{"Root"})
	if err != nil {
		t.Fatalf("ParseSource: %v", err)
	}
	out := RenderTypes(model, UnionsModule)
	if strings.Contains(out, "import") {
		t.Errorf("output imports something with no union to import:\n%s", out)
	}
}

func TestRenderSchema(t *testing.T) {
	out := RenderSchema(parseSample(t))

	for _, want := range []string{
		"// Code generated by internal/tsgen",
		"export const SCHEMA",
		`Root: [`,
		`{ key: "timestamp", type: { kind: "string" } }`,
		`{ key: "host", type: { kind: "object", ref: "Host" } }`,
		// A slice is nullable because a nil one marshals to null, and its
		// element shape is what makes element-level validation possible at all.
		`{ key: "items", type: { kind: "array", elem: { kind: "object", ref: "Item" }, nullable: true } }`,
		`{ key: "tags", type: { kind: "array", elem: { kind: "string" }, nullable: true } }`,
		`{ key: "detail", optional: true, type: { kind: "object", ref: "Detail", nullable: true } }`,
	} {
		if !strings.Contains(out, want) {
			t.Errorf("schema is missing %q", want)
		}
	}

	// A named string type validates as a string: which values are legal is the
	// union's job in the interface, and refusing a whole frame over a value the
	// build has not heard of would blank the dashboard.
	if !strings.Contains(out, `{ key: "state", type: { kind: "string" } }`) {
		t.Error("a named string type should validate as a plain string")
	}
}

// TestRenderSchema_UnreachableFieldShape is the belt to convertType's braces:
// a Type with no kind set cannot arise from a parse, but the renderer must not
// emit malformed TypeScript if one ever does.
func TestRenderSchema_UnreachableFieldShape(t *testing.T) {
	got := schemaShape(Type{Kind: KindArray})
	if got != `{ kind: "array", elem: { kind: "unknown" } }` {
		t.Errorf("schemaShape of an array with no element = %q", got)
	}
	if got := tsShape(Type{Kind: KindArray}); got != "unknown[]" {
		t.Errorf("tsShape of an array with no element = %q", got)
	}
}

// TestGenerate runs the whole thing against the real pkg/types/types.go.
//
// The unit tests above use a miniature so their expectations are readable; this
// one exists because the file the generator actually runs on is the only proof
// that every shape in it is one the generator knows. A new Go type the mapping
// cannot spell fails here, in `make test`, rather than in whoever next runs
// `make generate`.
func TestGenerate(t *testing.T) {
	out := t.TempDir()
	if err := Generate(filepath.Join("..", "..", "pkg", "types", "types.go"), out); err != nil {
		t.Fatalf("Generate against the real wire types: %v", err)
	}

	types, err := os.ReadFile(filepath.Join(out, TypesFile)) //nolint:gosec // the test's own temp dir
	if err != nil {
		t.Fatalf("read %s: %v", TypesFile, err)
	}
	schema, err := os.ReadFile(filepath.Join(out, SchemaFile)) //nolint:gosec // the test's own temp dir
	if err != nil {
		t.Fatalf("read %s: %v", SchemaFile, err)
	}

	// The root, and the fields whose absence from the hand-written mirror is
	// what made this worth generating (#38).
	for _, want := range []string{
		"export interface Snapshot {",
		"export interface WirelessInfo {",
		"  version: string;",
		"  wireless?: WirelessInfo | null;",
	} {
		if !strings.Contains(string(types), want) {
			t.Errorf("%s is missing %q", TypesFile, want)
		}
	}
	if !strings.Contains(string(schema), "Snapshot: [") {
		t.Errorf("%s has no entry for Snapshot", SchemaFile)
	}
	if !strings.Contains(string(schema), `{ key: "networks", type: { kind: "array", elem: { kind: "object", ref: "NetworkInfo" }, nullable: true } }`) {
		t.Errorf("%s does not describe the element type of networks, which is what makes element-level validation possible", SchemaFile)
	}
}

func TestGenerate_UnwritableOutput(t *testing.T) {
	// A path whose parent is a file, not a directory: the write cannot succeed
	// and must come back as a typed error naming the path.
	dir := t.TempDir()
	blocker := filepath.Join(dir, "blocker")
	if err := os.WriteFile(blocker, []byte("x"), 0o600); err != nil {
		t.Fatalf("write blocker: %v", err)
	}

	_, err := stageFile(filepath.Join(blocker, TypesFile), "content")
	if err == nil {
		t.Fatal("writing under a regular file returned no error")
	}
	var writeErr *WriteError
	if !errors.As(err, &writeErr) {
		t.Fatalf("error = %T (%v), want *WriteError", err, err)
	}
	if !strings.Contains(writeErr.Error(), TypesFile) {
		t.Errorf("error = %q, want it to name the file", writeErr)
	}
}

// TestGenerate_MissingSource covers the caller pointing the generator at a file
// that is not there, which is what a moved types.go looks like.
func TestGenerate_MissingSource(t *testing.T) {
	err := Generate(filepath.Join(t.TempDir(), "absent.go"), t.TempDir())
	if err == nil {
		t.Fatal("Generate on a missing source returned no error")
	}
	var srcErr *SourceError
	if !errors.As(err, &srcErr) {
		t.Fatalf("error = %T (%v), want *SourceError", err, err)
	}
}

func TestWriteDoc(t *testing.T) {
	var b strings.Builder
	writeDoc(&b, "One line.", "  ")
	if got := b.String(); got != "  /** One line. */\n" {
		t.Errorf("one-line doc = %q", got)
	}

	b.Reset()
	writeDoc(&b, "First.\n\nSecond.", "")
	want := "/**\n * First.\n *\n * Second.\n */\n"
	if got := b.String(); got != want {
		t.Errorf("multi-line doc = %q, want %q", got, want)
	}
}

func TestWriteDoc_Empty(t *testing.T) {
	var b strings.Builder
	writeDoc(&b, "", "  ")
	if got := b.String(); got != "" {
		t.Errorf("empty doc rendered %q, want nothing at all", got)
	}
}

// TestGenerate_FailedWriteLeavesThePairUntouched guards the pair's
// consistency: interfaces regenerated beside a schema that was not would
// disagree while both looked current.
func TestGenerate_FailedWriteLeavesThePairUntouched(t *testing.T) {
	out := t.TempDir()
	typesPath := filepath.Join(out, TypesFile)
	if err := os.WriteFile(typesPath, []byte("old types"), 0o600); err != nil {
		t.Fatalf("seed %s: %v", TypesFile, err)
	}
	// A directory where the schema file belongs: that write cannot succeed.
	if err := os.Mkdir(filepath.Join(out, SchemaFile), 0o700); err != nil {
		t.Fatalf("block %s: %v", SchemaFile, err)
	}

	err := Generate(filepath.Join("..", "..", "pkg", "types", "types.go"), out)
	if err == nil {
		t.Fatal("Generate succeeded with an unwritable schema destination")
	}
	var writeErr *WriteError
	if !errors.As(err, &writeErr) {
		t.Fatalf("error = %T (%v), want *WriteError", err, err)
	}

	got, readErr := os.ReadFile(typesPath) //nolint:gosec // the test's own temp dir
	if readErr != nil {
		t.Fatalf("read %s: %v", TypesFile, readErr)
	}
	if string(got) != "old types" {
		t.Errorf("%s was replaced although the schema write failed", TypesFile)
	}
	entries, dirErr := os.ReadDir(out)
	if dirErr != nil {
		t.Fatalf("read dir: %v", dirErr)
	}
	if len(entries) != 2 {
		t.Errorf("output dir holds %d entries, want only the two it started with (no staged leftovers)", len(entries))
	}
}

// TestGenerate_FailedRenameRestoresThePair covers the last step that can fail:
// the second rename, after the first has already replaced its file. The first
// replacement must be undone so the pair on disk is still the old, consistent
// one.
func TestGenerate_FailedRenameRestoresThePair(t *testing.T) {
	out := t.TempDir()
	for name, content := range map[string]string{TypesFile: "old types", SchemaFile: "old schema"} {
		if err := os.WriteFile(filepath.Join(out, name), []byte(content), 0o600); err != nil {
			t.Fatalf("seed %s: %v", name, err)
		}
	}

	injected := errors.New("rename refused")
	realRename := rename
	t.Cleanup(func() { rename = realRename })
	// Only the replacement of the schema fails; restoring it from its backup,
	// which renames onto the same path, must still work.
	refused := false
	rename = func(from, to string) error {
		if to == filepath.Join(out, SchemaFile) && !refused {
			refused = true
			return injected
		}
		return realRename(from, to)
	}

	err := Generate(filepath.Join("..", "..", "pkg", "types", "types.go"), out)
	if !errors.Is(err, injected) {
		t.Fatalf("error = %v, want the refused rename", err)
	}

	for name, want := range map[string]string{TypesFile: "old types", SchemaFile: "old schema"} {
		got, readErr := os.ReadFile(filepath.Join(out, name)) //nolint:gosec // the test's own temp dir
		if readErr != nil {
			t.Fatalf("read %s: %v", name, readErr)
		}
		if string(got) != want {
			t.Errorf("%s = %q, want the old %q restored", name, got, want)
		}
	}
	entries, dirErr := os.ReadDir(out)
	if dirErr != nil {
		t.Fatalf("read dir: %v", dirErr)
	}
	if len(entries) != 2 {
		t.Errorf("output dir holds %d entries, want only the pair (no staged or backup leftovers)", len(entries))
	}
}

// TestGenerate_FirstRunCreatesThePair covers an empty output directory, where
// there is nothing to back up and nothing to restore.
func TestGenerate_FirstRunCreatesThePair(t *testing.T) {
	out := t.TempDir()
	if err := Generate(filepath.Join("..", "..", "pkg", "types", "types.go"), out); err != nil {
		t.Fatalf("Generate: %v", err)
	}
	entries, err := os.ReadDir(out)
	if err != nil {
		t.Fatalf("read dir: %v", err)
	}
	if len(entries) != 2 {
		t.Errorf("output dir holds %d entries, want exactly the pair", len(entries))
	}
}

// TestGenerate_UnrestorableBackupIsKept covers the worst case: a replacement
// fails and putting the original back fails too. The backup is then the only
// copy of the original, so it must survive and the error must name it.
func TestGenerate_UnrestorableBackupIsKept(t *testing.T) {
	out := t.TempDir()
	for name, content := range map[string]string{TypesFile: "old types", SchemaFile: "old schema"} {
		if err := os.WriteFile(filepath.Join(out, name), []byte(content), 0o600); err != nil {
			t.Fatalf("seed %s: %v", name, err)
		}
	}

	injected := errors.New("rename refused")
	realRename := rename
	t.Cleanup(func() { rename = realRename })
	// Refuse replacing the schema, and refuse every restore of the types file.
	schemaRefused := false
	rename = func(from, to string) error {
		if to == filepath.Join(out, SchemaFile) && !schemaRefused {
			schemaRefused = true
			return injected
		}
		if to == filepath.Join(out, TypesFile) && strings.Contains(from, ".bak.") {
			return injected
		}
		return realRename(from, to)
	}

	err := Generate(filepath.Join("..", "..", "pkg", "types", "types.go"), out)
	if !errors.Is(err, injected) {
		t.Fatalf("error = %v, want the refused rename", err)
	}

	backups, globErr := filepath.Glob(filepath.Join(out, "."+TypesFile+".bak.*"))
	if globErr != nil {
		t.Fatalf("glob: %v", globErr)
	}
	if len(backups) != 1 {
		t.Fatalf("found %d backups of %s, want the one that could not be restored kept", len(backups), TypesFile)
	}
	kept, readErr := os.ReadFile(backups[0]) //nolint:gosec // the test's own temp dir
	if readErr != nil {
		t.Fatalf("read backup: %v", readErr)
	}
	if string(kept) != "old types" {
		t.Errorf("backup = %q, want the original content", kept)
	}
	if !strings.Contains(err.Error(), backups[0]) {
		t.Errorf("error %q does not name the kept backup %s", err, backups[0])
	}
}

// TestRenderTypes_PointerElementsKeepTheirNull covers []*T: encoding/json
// sends a nil element as null, and the schema accepts it, so the interface
// has to say so or a caller dereferences a null behind a type that forbids it.
func TestRenderTypes_PointerElementsKeepTheirNull(t *testing.T) {
	const src = `package types

type Child struct {
	N int ` + "`json:\"n\"`" + `
}

type Root struct {
	Kids []*Child ` + "`json:\"kids\"`" + `
}
`
	model, err := ParseSource("ptr.go", src, []string{"Root"})
	if err != nil {
		t.Fatalf("ParseSource: %v", err)
	}
	if out := RenderTypes(model, "./unions"); !strings.Contains(out, "  kids: (Child | null)[];") {
		t.Errorf("RenderTypes did not spell nullable elements:\n%s", out)
	}
}

// TestRenderTypes_NonIdentifierKeysAreQuoted covers a legal json tag such as
// "display-name", which is not a TypeScript identifier and must be quoted as
// a property name or the emitted file does not compile.
func TestRenderTypes_NonIdentifierKeysAreQuoted(t *testing.T) {
	const src = `package types

type Root struct {
	Display string ` + "`json:\"display-name\"`" + `
	Maybe   string ` + "`json:\"may.be,omitempty\"`" + `
	Plain   string ` + "`json:\"plain_name\"`" + `
}
`
	model, err := ParseSource("keys.go", src, []string{"Root"})
	if err != nil {
		t.Fatalf("ParseSource: %v", err)
	}
	out := RenderTypes(model, "./unions")
	for _, want := range []string{`  "display-name": string;`, `  "may.be"?: string;`, "  plain_name: string;"} {
		if !strings.Contains(out, want) {
			t.Errorf("RenderTypes is missing %q:\n%s", want, out)
		}
	}
}
